import SwiftUI

/// The crisis screen. Its wording and resources are fixed here, never generated by the model. Resources must be
/// verified and kept current by people before release; regions other than the US get the international helpline
/// directory and the local emergency number.
struct CrisisView: View {
    @Environment(\.dismiss) private var dismiss
    private let isUS = Locale.current.region?.identifier == "US"

    var body: some View {
        NavigationStack {
            List {
                Section {
                    Text("You don't have to go through this alone. If you might act on thoughts of harming yourself or someone else, please reach out to someone now.")
                }
                if isUS {
                    Section("Talk to someone now (US)") {
                        Link(destination: URL(string: "tel:988")!) {
                            Label("Call 988 Suicide & Crisis Lifeline", systemImage: "phone.fill")
                        }
                        Link(destination: URL(string: "sms:988")!) {
                            Label("Text 988", systemImage: "message.fill")
                        }
                        Link(destination: URL(string: "sms:741741&body=HOME")!) {
                            Label("Text HOME to 741741 (Crisis Text Line)", systemImage: "message")
                        }
                        Link(destination: URL(string: "tel:911")!) {
                            Label("Emergency: call 911", systemImage: "staroflife.fill")
                        }
                        .foregroundStyle(.red)
                    }
                } else {
                    Section("Talk to someone now") {
                        Link(destination: URL(string: "https://findahelpline.com")!) {
                            Label("Find a free, confidential helpline in your country", systemImage: "globe")
                        }
                        Text("In an emergency, call your local emergency number.")
                            .foregroundStyle(.red)
                    }
                }
                Section("A moment to ground yourself") {
                    Text("Breathe in slowly for 4 counts, hold for 4, out for 6. Then name 5 things you can see, 4 you can touch, 3 you can hear, 2 you can smell and 1 you can taste.")
                }
                Section {
                    Text("Companion is not a therapist or an emergency service, and it can't contact anyone for you.")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }
            }
            .navigationTitle("Support")
            .toolbar { Button("Back to chat") { dismiss() } }
        }
    }
}
